#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++){ scanf("%d",&p[i]); p[i]--; }

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    // Place elements 0,1,...,n-1 into positions 0,1,...
    for(int t=0; t<n-1; t++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==t){ pos=i; break; }
        if(pos==t) continue;

        // Step 1: bring element to position t (the front of unsorted region)
        // We want to move p[pos] to position t
        // If pos > t:
        //   Use x=t, y= n-pos. Then suffix = p[pos..n-1], middle = p[t..pos-1], prefix=p[0..t-1]
        //   Result: [p[pos..n-1], p[t..pos-1], p[0..t-1]]
        //   Element is now at position 0... we want it at position t.
        //   Hmm. Let me try: x=t+1, y=n-pos if t+1+n-pos <= n-1, i.e., t+1 <= pos-1, i.e., t < pos-1
        if(pos == t) continue;
        if(pos > t+1 && t+1 + (n-pos) <= n-1){
            apply(t+1, n-pos); 
            // suffix=[pos..n-1] (size n-pos), element at index 0 of result
            // prefix=[0..t] goes to end
            // element t is at position n-pos - 1... no, at position 0 of suffix = position 0
            // Need another op to fix: x=1, y=... let's just move from pos=0 to t
            if(t >= 1) apply(1, n-1-t);
            // suffix of size n-1-t goes first, then middle, then prefix(1)=[elem]
            // elem goes to position n-1... that's wrong too
        } else {
            // Brute force: rotate
            if(pos > 0 && pos < n-1)
                apply(pos, 1);
            else if(pos == 0 && n>=3)
                apply(1, n-2);
            else
                apply(n-2, 1);
            t--; // retry
        }
        if((int)ops.size() > 4*n) break;
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
